- (void)command:(NSString *)name { [self.web evaluateJavaScript:[NSString stringWithFormat:@"window.appCommand(%@)",[SYJSON(@[name])substringWithRange:NSMakeRange(1,SYJSON(@[name]).length-2)]]completionHandler:nil]; }
#define SY_COMMAND(method,name) - (void)method:(id)sender { [self command:@name]; }
SY_COMMAND(importSublime,"importSublime") SY_COMMAND(newNote,"new") SY_COMMAND(settings,"settings") SY_COMMAND(openFiles,"open") SY_COMMAND(saveFile,"saveFile") SY_COMMAND(saveAs,"saveAs") SY_COMMAND(closeTab,"closeTab") SY_COMMAND(quickOpen,"quickOpen") SY_COMMAND(search,"search") SY_COMMAND(find,"find") SY_COMMAND(chat,"chat") SY_COMMAND(archive,"archive") SY_COMMAND(wrap,"wrap") SY_COMMAND(backup,"backup") SY_COMMAND(restore,"restore") SY_COMMAND(help,"help")
- (void)about:(id)sender { [NSApp orderFrontStandardAboutPanelWithOptions:@{NSAboutPanelOptionApplicationName:@"拾页 Shiye",NSAboutPanelOptionApplicationVersion:@"1.1.1",NSAboutPanelOptionCredits:[[NSAttributedString alloc]initWithString:@"随手记下，让知识留下。\n本地优先的 AI 草稿本"]}]; }
- (BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication *)sender { return YES; }
- (BOOL)windowShouldClose:(NSWindow *)sender { [NSApp terminate:nil];return NO; }
- (NSApplicationTerminateReply)applicationShouldTerminate:(NSApplication *)sender {
    if(!self.loaded)return NSTerminateNow;if(self.terminationPending)return NSTerminateLater;self.terminationPending=YES;
    [self.web evaluateJavaScript:@"window.flushAllForClose()"completionHandler:^(id value,NSError *error){if(error){self.terminationPending=NO;[NSApp replyToApplicationShouldTerminate:NO];NSAlert *alert=[NSAlert new];alert.messageText=@"草稿尚未完成保存";alert.informativeText=@"请返回编辑器确认本地保存成功后再退出。";[alert runModal];}}];return NSTerminateLater;
}
- (void)application:(NSApplication *)sender openFiles:(NSArray<NSString *> *)filenames { for(NSString *path in filenames)[self.pendingFiles addObject:[NSURL fileURLWithPath:path]];if(self.loaded)[self importPending];[NSApp replyToOpenOrPrint:NSApplicationDelegateReplySuccess]; }
- (void)importPending { NSError *error=nil;NSDictionary *result=[self.store importFiles:self.pendingFiles error:&error];[self.pendingFiles removeAllObjects];[self emit:error?@"error":@"filesOpened"value:error?@{@"message":error.localizedDescription}:result]; }
- (void)webView:(WKWebView *)webView didFinishNavigation:(WKNavigation *)navigation { self.loaded=YES;if(self.pendingFiles.count)[self importPending]; }
- (void)webView:(WKWebView *)webView decidePolicyForNavigationAction:(WKNavigationAction *)action decisionHandler:(void (^)(WKNavigationActionPolicy))decisionHandler { decisionHandler(action.request.URL.isFileURL?WKNavigationActionPolicyAllow:WKNavigationActionPolicyCancel); }
- (void)emit:(NSString *)name value:(id)value { [self.web evaluateJavaScript:[NSString stringWithFormat:@"window.nativeEvent(%@)",SYJSON(@{@"name":name,@"data":value?:NSNull.null})]completionHandler:nil]; }
- (void)reply:(NSString *)identifier result:(id)result error:(NSError *)error {
    NSMutableDictionary *message=[@{@"id":identifier,@"result":result?:NSNull.null}mutableCopy];if(error)message[@"error"]=error.localizedDescription;
    [self.web evaluateJavaScript:[NSString stringWithFormat:@"window.nativeReply(%@)",SYJSON(message)]completionHandler:nil];
}
- (NSDictionary *)provider { NSMutableDictionary *settings=[SYDefaultSettings()mutableCopy];id stored=SYParse([self.store setting:@"provider"]?:@"{}");if([stored isKindOfClass:NSDictionary.class])[settings addEntriesFromDictionary:stored];settings[@"hasKey"]=@(SYHasKey());return settings; }
- (void)userContentController:(WKUserContentController *)controller didReceiveScriptMessage:(WKScriptMessage *)message {
    if(!message.frameInfo.isMainFrame||!message.frameInfo.request.URL.isFileURL||![message.body isKindOfClass:NSDictionary.class])return;NSDictionary *body=message.body;NSString *identifier=body[@"id"],*action=body[@"action"];if(![identifier isKindOfClass:NSString.class]||![action isKindOfClass:NSString.class])return;NSDictionary *args=[body[@"args"]isKindOfClass:NSDictionary.class]?body[@"args"]:@{};
    @try {[self handle:action args:args completion:^(id result,NSError *error){[self reply:identifier result:result error:error];}];}
    @catch(NSException *exception){[self reply:identifier result:nil error:SYError(@"数据格式不正确，操作未完成。")];}
}
- (void)handle:(NSString *)action args:(NSDictionary *)args completion:(SYCompletion)done {
