        NSMutableArray *items=[NSMutableArray array];for(NSDictionary *entry in snapshot[@"entries"]){[items addObject:@{@"id":entry[@"id"],@"title":entry[@"title"],@"file":entry[@"file"],@"window":entry[@"window"],@"characters":@([entry[@"content"]length]),@"unsaved":entry[@"unsaved"],@"duplicate":@([existing containsObject:entry[@"fingerprint"]]),@"excerpt":SYClip(SYRedact(SYClip(entry[@"content"],2000)),150)}];}
        NSMutableDictionary *result=[snapshot mutableCopy];[result removeObjectForKey:@"entries"];result[@"items"]=items;result[@"token"]=self.sublimeToken;done(result,nil);
    });return;}
    else if([action isEqual:@"importSublime"]){if(![args[@"token"]isEqual:self.sublimeToken]){done(nil,SYError(@"Sublime 预览已更新，请重新选择文本。"));return;}NSSet *selected=[NSSet setWithArray:args[@"ids"]?:@[]];NSMutableArray *entries=[NSMutableArray array];for(NSDictionary *entry in self.sublimeSnapshot[@"entries"])if([selected containsObject:entry[@"id"]])[entries addObject:entry];if(!entries.count){done(nil,SYError(@"请至少选择一篇文本。"));return;}NSMutableDictionary *imported=[[self.store importSublimeEntries:entries error:&error]mutableCopy];if(imported){imported[@"notes"]=[self.store all:&error];result=imported;}}
    else if([action isEqual:@"planArchive"]){NSArray *ids=args[@"ids"]?:@[];if(!ids.count||ids.count>2000){done(nil,SYError(@"请选择 1–2000 篇草稿。"));return;}NSMutableArray *notes=[NSMutableArray array];NSMutableSet *seen=[NSMutableSet set];for(NSString *identifier in ids){if([seen containsObject:identifier])continue;[seen addObject:identifier];NSDictionary *note=[self.store note:identifier error:&error];if(!note||[note[@"trashed"]boolValue]||![note[@"kind"]isEqual:@"draft"]){done(nil,SYError(@"有草稿已不存在，请重新选择。"));return;}if(SYTrim(note[@"content"]).length)[notes addObject:note];}NSArray *batches=SYArchiveBatches(notes);if(!batches.count){done(nil,SYError(@"所选草稿没有可提炼的内容。"));return;}NSString *token=NSUUID.UUID.UUIDString;[self.archivePlans removeAllObjects];self.archivePlans[token]=batches;NSMutableArray *preview=[NSMutableArray array];for(NSArray *batch in batches){NSUInteger length=0;NSMutableArray *titles=[NSMutableArray array];for(NSDictionary *part in batch){length+=[part[@"length"]unsignedIntegerValue];NSDictionary *note=[self.store note:part[@"id"]error:&error];[titles addObject:note[@"title"]];}[preview addObject:@{@"characters":@(length),@"count":@(batch.count),@"titles":titles}];}result=@{@"token":token,@"batches":preview,@"sourceCount":@(notes.count)};}
