        if(!key.length&&![args[@"deleteKey"]boolValue]){NSURL *current=SYModelsEndpoint([self provider],nil),*requested=SYModelsEndpoint(args[@"settings"],nil);if(current&&[current isEqual:requested])key=SYKey();}
