    else if([action isEqual:@"extract"]){NSArray *ids=args[@"ids"]?:@[];if(!ids.count||ids.count>20){done(nil,SYError(@"每次请选择 1–20 篇草稿。"));return;}NSMutableArray *notes=[NSMutableArray array];for(NSString *identifier in ids){NSDictionary *note=[self.store note:identifier error:&error];if(!note||[note[@"trashed"]boolValue]){done(nil,SYError(@"原始草稿不存在。"));return;}[notes addObject:note];}SYCompletion finish=^(id proposal,NSError *failure){if(failure){done(nil,failure);return;}NSString *token=NSUUID.UUID.UUIDString;self.proposals[token]=proposal;done(@{@"token":token,@"proposal":proposal},nil);};if([args[@"local"]boolValue])finish(SYLocalProposal(notes),nil);else SYExtract(notes,[self provider],SYKey(),finish);return;}
    else if([action isEqual:@"acceptProposal"]){NSString *token=args[@"token"];NSDictionary *proposal=self.proposals[token];if(!proposal)error=SYError(@"整理预览已失效，请重新生成。");else{NSArray *created=[self.store accept:proposal knowledge:[args[@"knowledge"]boolValue]skill:[args[@"skill"]boolValue]error:&error];if(created){[self.proposals removeObjectForKey:token];NSArray *notes=[self.store all:&error];result=notes?@{@"created":created,@"notes":notes}:nil;}}}
    else if([action isEqual:@"chat"]){NSString *question=SYTrim(args[@"question"]);if(!question.length){done(nil,SYError(@"请输入问题。"));return;}NSArray *hits=[self.store search:question limit:6 error:&error],*history=args[@"history"]?:@[];if(!hits.count)for(NSDictionary *message in history.reverseObjectEnumerator)if([message[@"role"]isEqual:@"user"]){hits=[self.store search:message[@"content"]limit:6 error:&error];break;}if(error){done(nil,error);return;}NSDictionary *settings=[self provider];if(!hits.count)result=@{@"answer":@"当前草稿中没有找到相关内容。试试输入服务名、命令名或问题中的关键字。",@"mode":@"retrieval",@"sources":@[]};else if(![settings[@"baseURL"]length]||![settings[@"model"]length]){NSMutableArray *parts=[NSMutableArray array];NSUInteger index=0;for(NSDictionary *hit in hits)[parts addObject:[NSString stringWithFormat:@"[%lu] %@\n%@",(unsigned long)++index,hit[@"note"][@"title"],hit[@"excerpt"]]];result=@{@"answer":[NSString stringWithFormat:@"已找到 %lu 篇相关内容。配置公司模型后，可以基于这些来源生成回答。\n\n%@",(unsigned long)hits.count,[parts componentsJoinedByString:@"\n\n"]],@"mode":@"retrieval",@"sources":hits};}else{SYAnswer(question,hits,history,settings,SYKey(),^(id answer,NSError *failure){done(failure?nil:@{@"answer":answer,@"mode":@"ai",@"sources":hits},failure);});return;}}
